.now { font-size: 27px; font-weight: 800; color: #14202e; letter-spacing: -.02em; }
.was { text-decoration: line-through; color: #8b95a3; font-size: 14px; }
.off { background: #c2410c; color: #fff; border-radius: 4px; padding: 3px 7px; font-size: 12px; font-weight: 800; }
.score-line { margin: 0 0 8px; font-size: 13px; }
.score-label { color: #5a6472; }
.score-value { font-weight: 800; color: #14202e; }
.note { font-size: 13px; color: #45515f; margin: 0 0 14px; flex: 1; }
.meta { font-size: 11px; color: #7a8492; margin: 0 0 12px; border-top: 1px dashed #ded8ca; padding-top: 10px; }
.actions { margin-top: auto; }
.store-link { display: block; text-align: center; background: #e8a33d; color: #17202b; font-weight: 800; text-decoration: none; border-radius: 6px; padding: 10px; }
.store-link:hover { background: #f2b65a; }
.empty { background: #fff; border: 1px dashed #cbd2da; border-radius: 8px; padding: 40px; text-align: center; margin-top: 20px; }

footer { background: #14202e; color: #b8c5d4; padding: 22px 0; font-size: 13px; }
footer p { margin: 4px 0; }

@media (max-width: 900px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
  .filter-row, .filter-row.second { grid-template-columns: 1fr 1fr; }
  .filter-row.second button { grid-column: 1 / -1; }
}
@media (max-width: 600px) {
  .head-row { flex-direction: column; align-items: flex-start; }
  .filter-row, .filter-row.second { grid-template-columns: 1fr; }
  .filter-row.second button { grid-column: auto; }
  .grid { grid-template-columns: 1fr; }
  .hero { padding: 26px 0 24px; }
  .now { font-size: 24px; }
}
